use crate::cad::io::sqlite::snapshot::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->SemioCadSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let a=SemioPoint2{x:1.0,y:2.0};let b=SemioPoint2{x:3.0,y:4.0};let entities=vec![CadEntity::Line{a,b},CadEntity::Arc{center:a,radius:2.5,start_angle:-1.0,end_angle:5.0},CadEntity::Circle{center:b,radius:2.5},CadEntity::Ellipse{center:a,major_axis_end:b,ratio:0.75,start_param:-1.0,end_param:5.0},CadEntity::Polyline{vertices:vec![a,b,a],closed:true},CadEntity::Text{position:b,height:12.5,rotation:-1.5,content:f["text"].as_str().unwrap().into()},CadEntity::Insert{block_name:f["blockName"].as_str().unwrap().into(),insertion_point:a,scale:b,rotation:0.25},CadEntity::Solid{p1:a,p2:b,p3:SemioPoint2{x:5.0,y:6.0},p4:SemioPoint2{x:7.0,y:8.0}},CadEntity::Dimension{def_point:a,text_position:b,measurement:13.75,text:f["text"].as_str().unwrap().into()}];SemioCadSnapshot{schema:f["schema"].as_str().unwrap().into(),layers:(0..2).map(|i|CadLayer{name:f["layerNames"][i].as_str().unwrap().into(),color_index:f["colorIndices"][i].as_i64().unwrap() as i32,line_type:f["lineTypes"][i].as_str().unwrap().into(),visible:i==0}).collect(),blocks:vec![CadBlock{name:f["blockName"].as_str().unwrap().into(),base_point:SemioPoint2{x:1.5,y:-2.5},entities:vec![CadEntityRecord{handle:"block-line".into(),layer:"hidden".into(),entity:CadEntity::Line{a,b}}]}],entities:entities.into_iter().enumerate().map(|(i,entity)|CadEntityRecord{handle:format!("entity-{i}"),layer:if i%2==0{"visible"}else{"hidden"}.into(),entity}).collect()}}
fn project(value:&SemioCadSnapshot)->SqliteDatabase{value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioCadSnapshot, semio_framework_value::ValueError>{SemioCadSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_cad_all_nine_entity_variants_blocks_layers_full_scalar_ranges_and_native_state(){let snapshot=fixture();let bytes=export_sqlite_database(&project(&snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored,snapshot);assert_eq!(<SemioCadSnapshot as store::ArtifactPack>::encode_pack(&restored),<SemioCadSnapshot as store::ArtifactPack>::encode_pack(&snapshot));assert_eq!(<SemioCadSnapshot as store::ArtifactDsl>::print_dsl(&restored),<SemioCadSnapshot as store::ArtifactDsl>::print_dsl(&snapshot));assert_eq!(restore(&project(&SemioCadSnapshot::default())).unwrap(),SemioCadSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_cad_rejects_variant_shape_layer_block_order_and_budget_corruption(){let original=project(&fixture());for change in 0..5{let mut db=original.clone();match change{0=>db.table_mut("semio_cad_entity").unwrap().rows[0].values[5]=SqliteValue::Integer(999),1=>db.table_mut("semio_cad_insert").unwrap().rows[0].values[1]=SqliteValue::Integer(999),2=>db.table_mut("semio_cad_polyline_vertex").unwrap().rows[0].values[2]=SqliteValue::Integer(99),3=>{db.table_mut("semio_cad_arc").unwrap().rows.clear();},_=>db.table_mut("semio_cad_layer").unwrap().rows[0].values[4]=SqliteValue::Integer(i64::MAX)}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioCadSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_cad_independent_layer_entity_join_and_text_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=db.query('SELECT handle,name FROM semio_cad_entity JOIN semio_cad_layer ON layer_id=semio_cad_layer.id JOIN semio_cad_text ON semio_cad_text.id=semio_cad_entity.id').get();if(r.handle!=='entity-5'||r.name!=='hidden')throw Error('layer relationship');db.query(\"UPDATE semio_cad_text SET content='independently edited'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();if let CadEntity::Text{content,..}=&mut expected.entities[5].entity{*content="independently edited".into();}assert_eq!(restored,expected);}

